    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case MeshComponent components:
                Components ??= [];
                if (!Components.Contains(components))
                {
                    Components = [..Components, components];
                    ModifiedParameters[nameof(Components)] = Components;
                }
                
                return true;
            case MeshTransform transform:
                if (transform != Transform)
                {
                    Transform = transform;
                    ModifiedParameters[nameof(Transform)] = Transform;
                }
                
                return true;
            case MeshVertexAttributes vertexAttributes:
                if (vertexAttributes != VertexAttributes)
                {
                    VertexAttributes = vertexAttributes;
                    ModifiedParameters[nameof(VertexAttributes)] = VertexAttributes;
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case MeshComponent components:
                Components = Components?.Where(c => c != components).ToList();
                ModifiedParameters[nameof(Components)] = Components;
                return true;
            case MeshTransform _:
                Transform = null;
                ModifiedParameters[nameof(Transform)] = Transform;
                return true;
            case MeshVertexAttributes _:
                VertexAttributes = null;
                ModifiedParameters[nameof(VertexAttributes)] = VertexAttributes;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        if (Components is not null)
        {
            foreach (MeshComponent child in Components)
            {
                child.ValidateRequiredGeneratedChildren();
            }
        }
        Transform?.ValidateRequiredGeneratedChildren();
        VertexAttributes?.ValidateRequiredGeneratedChildren();
        base.ValidateRequiredGeneratedChildren();
    }
      
